        self.wfile.flush()


def run(binary):
    binary = str(Path(binary).absolute())
    before = hashlib.sha256(Path(binary).read_bytes()).hexdigest()
    rows = []
    for mode in ('final', 'tools', 'max', 'tool_max', 'context', 'thinking', 'refusal', 'error', 'disconnect', 'cancel'):
